'use strict';
const G=window.Blackthorn,$=id=>document.getElementById(id),key='astra-blackthorn-v2';let state=null,rendered=0;
function valid(s){return s&&s.version===2&&G.classes[s.cls]&&(G.scenes[s.scene]||s.end)&&typeof s.name==='string'&&Array.isArray(s.log)&&s.log.every(e=>e&&typeof e.text==='string')&&Array.isArray(s.flags)&&Array.isArray(s.journal)&&Number.isFinite(s.hp)&&Number.isFinite(s.maxHp)&&Number.isFinite(s.potions)&&Number.isFinite(s.gold)&&(!s.enemy||(typeof s.enemy.name==='string'&&Number.isFinite(s.enemy.hp)&&['guard','drowned','boss'].includes(s.enemy.kind)));}
try{const data=JSON.parse(localStorage.getItem(key));if(valid(data))state=data}catch{}
function appendLog(){const log=$('story');if(rendered>state.log.length||rendered===0){log.replaceChildren();rendered=0}for(const e of state.log.slice(rendered)){const div=document.createElement('div');div.className='entry '+e.kind;const h=document.createElement('h4');h.textContent=e.title;const p=document.createElement('p');p.textContent=e.text;div.append(h,p);log.append(div)}rendered=state.log.length;log.scrollTop=log.scrollHeight}
function render(){const playing=!!state;$('creation').hidden=playing;$('game').hidden=!playing;if(!playing)return;const c=G.classes[state.cls];$('heroName').textContent=state.name;$('heroClass').textContent='LEVEL 2 '+c.name.toUpperCase()+' · '+c.weapon;$('hp').textContent=state.hp+' / '+state.maxHp;$('ac').textContent=state.ac;$('health').style.width=(state.hp/state.maxHp*100)+'%';$('stats').replaceChildren();for(const[k,v]of Object.entries(c.stats)){const d=document.createElement('div');d.textContent=k;const b=document.createElement('b');b.textContent=(v>=0?'+':'')+v;d.append(b);$('stats').append(d)}$('pack').textContent=`${state.potions} healing potions · ${state.gold} gold`+(state.cls==='wizard'?` · ${state.slots}/3 spell slots`:'');$('abilities').textContent=c.ability;$('journal').replaceChildren();for(const text of state.journal){const li=document.createElement('li');li.textContent=text;$('journal').append(li)}$('chapter').textContent=state.end||G.scenes[state.scene].title;$('chapterNo').textContent=state.enemy?'ROLL INITIATIVE':G.scenes[state.scene]?.chapter.split(' / ')[0]||'EPILOGUE';appendLog();$('enemy').hidden=!state.enemy;$('enemy').textContent=state.enemy?`${state.enemy.name} · ${state.enemy.hp} / ${state.enemy.maxHp} HP · AC ${state.enemy.ac}`:'';$('dice').textContent=state.lastRoll?state.lastRoll.n:'d20';$('roll').textContent=state.lastRoll?.text||'Your fate is unwritten.';$('choices').replaceChildren();G.options(state).forEach((o,i)=>{const b=document.createElement('button');b.textContent=(i+1)+'. '+o.label;const hint=document.createElement('small');hint.textContent=o.hint;b.append(hint);b.onclick=()=>run(o.id);$('choices').append(b)});if(state.end){const b=document.createElement('button');b.className='primary';b.textContent='Begin another adventure';b.onclick=newGame;$('choices').append(b)}$('command').hidden=!!state.end;$('potion').disabled=!!state.end||!state.potions||state.hp===state.maxHp;$('rest').disabled=!!state.end||!!state.enemy||state.rested||state.hp===state.maxHp;try{localStorage.setItem(key,JSON.stringify(state));$('savestatus').textContent='PROGRESS SAVED ON THIS DEVICE'}catch{$('savestatus').textContent='SAVE UNAVAILABLE · KEEP THIS TAB OPEN'}}
function run(cmd){if(!state)return;if(state.log.length>=95)rendered=0;G.act(state,cmd);render()}
function newGame(){if(state&&!state.end&&!confirm('Start again? Your current adventure will be replaced.'))return;state=null;rendered=0;try{localStorage.removeItem(key)}catch{}render();window.scrollTo({top:0,behavior:'smooth'})}
$('heroform').onsubmit=e=>{e.preventDefault();state=G.fresh($('name').value,new FormData(e.target).get('class'));rendered=0;render();$('game').scrollIntoView({behavior:'smooth',block:'start'})};$('command').onsubmit=e=>{e.preventDefault();const cmd=$('input').value;$('input').value='';run(cmd)};$('potion').onclick=()=>run('potion');$('rest').onclick=()=>run('rest');$('newgame').onclick=newGame;for(const id of ['rules','credits'])$(id).onclick=()=>$('modal').showModal();$('close').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close()}};render();
